// Copies docs/guides/*.md into src/app/guides-content.ts so the Workers bundle can serve them
// without any bundler configuration. Run `npm run build:guides` after editing a guide; a test
// fails if the generated file is out of date.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const GUIDE_SLUGS = ['zapier', 'make', 'n8n', 'pipedream'];

export function generate() {
  const entries = GUIDE_SLUGS.map((slug) => {
    const markdown = readFileSync(join(root, 'docs', 'guides', `${slug}.md`), 'utf8').replace(/\r\n/g, '\n');
    return `  ${JSON.stringify(slug)}: ${JSON.stringify(markdown)},`;
  });
  return [
    '// GENERATED by scripts/build-guides.mjs from docs/guides/*.md. Do not edit by hand:',
    '// edit the Markdown file and run `npm run build:guides`.',
    '',
    'export const GUIDE_MARKDOWN: Record<string, string> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(root, 'src', 'app', 'guides-content.ts'), generate());
  console.log('wrote src/app/guides-content.ts');
}
